function onLoad()
	circle = {
		color             = {0, 1, 0}, --RGB color of the circle
		radius            = 24,           --radius of the circle around the object
		show              = true,       --should the circle be shown by default?
		steps             = 128,          --number of segments that make up the circle
		thickness         = 0.1,         --thickness of the circle line
		vertical_position = 1,           --vertical height of the circle relative to the object
	}
	self.setVectorLines({
		{
			points    = getCircleVectorPoints(circle.radius, circle.steps, circle.vertical_position),
			color     = circle.color,
			thickness = circle.thickness,
			rotation  = {0,0,0},
		}
	})
end





function getCircleVectorPoints(radius, steps, y)
	local t = {}
	local d,s,c,r = 360/steps, math.sin, math.cos, math.rad
	for i = 0,steps do
		table.insert(t, {
			c(r(d*i))*radius,
			y,
			s(r(d*i))*radius
		})
	end
	return t
end

